    if (typeof v !== k.tip) { hatalar.push(`${ad}: ${k.tip} olmali`); continue; }
    if (k.enAz && v.length < k.enAz) hatalar.push(`${ad}: en az ${k.enAz} karakter`);
    if (k.enCok && v.length > k.enCok) hatalar.push(`${ad}: en cok ${k.enCok} karakter`);
