function fark(eski, yeni) {
  const eskiIdx = new Map(eski.map((d, i) => [d.id, i]));
  const yeniId = new Set(yeni.map((d) => d.id));
  const islem = [];
  for (const d of eski) if (!yeniId.has(d.id)) islem.push('SIL#' + d.id);
  yeni.forEach((d, i) => {
    if (!eskiIdx.has(d.id)) islem.push('EKLE#' + d.id + '@' + i);
    else {
      const e = eski[eskiIdx.get(d.id)];
      if (e.baslik !== d.baslik) islem.push('GUNCELLE#' + d.id);
      if (eskiIdx.get(d.id) !== i) islem.push('TASI#' + d.id + '@' + i);
    }
  });
  return islem;
}
