function yapilandir(env) {
  const cfg = {}, hata = [];
  for (const [ad, k] of Object.entries(SEMA)) {
    let v = env[ad];
    if (v === undefined || v === '') {
      if (k.zorunlu) { hata.push(ad + ': eksik'); continue; }
      v = k.varsayilan;
    } else if (k.tip === 'sayi') {
      v = Number(v);
      if (!Number.isFinite(v)) { hata.push(ad + ': sayi olmali'); continue; }
    }
    if (k.kume && !k.kume.includes(v)) hata.push(ad + ': gecersiz deger');
    if (k.enAz && String(v).length < k.enAz) hata.push(ad + ': en az ' + k.enAz + ' karakter');
    cfg[ad] = v;
  }
  if (hata.length) throw new Error('Yapilandirma hatasi: ' + hata.join('; '));
  return cfg;
}
